// ============================================================================
// Module: soc_checker
// Minimal signal-driving checker comparing observed interface transactions
// against stimulus generated by peripheral sequences.
// ============================================================================

`uvm_analysis_imp_decl(_gpio)
`uvm_analysis_imp_decl(_uart)
`uvm_analysis_imp_decl(_encoder)
`uvm_analysis_imp_decl(_pwm)

class soc_checker extends uvm_component;
  uvm_analysis_imp_gpio    #(gpio_item, soc_checker)    gpio_export;
  uvm_analysis_imp_uart    #(uart_item, soc_checker)    uart_export;
  uvm_analysis_imp_encoder #(encoder_item, soc_checker) encoder_export;
  uvm_analysis_imp_pwm     #(pwm_item, soc_checker)     pwm_export;

  // Expected queues
  bit [31:0] expected_gpio_q[$];
  bit [1:0]  expected_enc_q[$];

  // Statistics counters
  int gpio_matches = 0;
  int gpio_mismatches = 0;
  int uart_rx_checks = 0;
  int enc_matches = 0;
  int enc_mismatches = 0;
  int pwm_samples = 0;

  `uvm_component_utils(soc_checker)

  function new(string name, uvm_component parent);
    super.new(name, parent);
    gpio_export    = new("gpio_export", this);
    uart_export    = new("uart_export", this);
    encoder_export = new("encoder_export", this);
    pwm_export     = new("pwm_export", this);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    // Initialize expected GPIO stimulus sequence
    expected_gpio_q.push_back(32'h5555_5555);
    expected_gpio_q.push_back(32'hAAAA_AAAA);
    expected_gpio_q.push_back(32'h0000_0001);
    expected_gpio_q.push_back(32'h8000_0000);
    expected_gpio_q.push_back(32'h0000_005A);

    // Initialize expected Encoder quadrature transitions: 10 -> 11 -> 01 -> 00
    expected_enc_q.push_back(2'b10);
    expected_enc_q.push_back(2'b11);
    expected_enc_q.push_back(2'b01);
    expected_enc_q.push_back(2'b00);
  endfunction

  // 1. GPIO Monitor Analysis Implementation
  virtual function void write_gpio(gpio_item item);
    if (!$isunknown(item.gpio_io)) begin
      if (expected_gpio_q.size() > 0) begin
        bit [31:0] exp_val = expected_gpio_q.pop_front();
        if (item.gpio_io !== exp_val) begin
          `uvm_error("GPIO_CHECKER", $sformatf("Mismatch: observed=0x%08h, expected=0x%08h", item.gpio_io, exp_val))
          gpio_mismatches++;
        end else begin
          `uvm_info("GPIO_CHECKER", $sformatf("Match: observed=0x%08h == expected=0x%08h", item.gpio_io, exp_val), UVM_LOW)
          gpio_matches++;
        end
      end else begin
        `uvm_error("GPIO_CHECKER", $sformatf("Unexpected extra GPIO transaction observed: 0x%08h", item.gpio_io))
        gpio_mismatches++;
      end
    end
  endfunction

  // 2. UART Monitor Analysis Implementation
  virtual function void write_uart(uart_item item);
    // Verify valid non-X/non-Z RX signal drive
    if (item.uart_rx === 1'bx) begin
      `uvm_error("UART_CHECKER", "Observed illegal X on uart_rx")
    end else begin
      uart_rx_checks++;
      `uvm_info("UART_CHECKER", $sformatf("Observed UART RX=%0b, TX=%0b, IRQ=%0b", item.uart_rx, item.uart_tx, item.uart_irq), UVM_HIGH)
    end
  endfunction

  // 3. Encoder Monitor Analysis Implementation
  virtual function void write_encoder(encoder_item item);
    bit [1:0] curr_enc = {item.enc_a, item.enc_b};
    if (expected_enc_q.size() > 0 && curr_enc == expected_enc_q[0]) begin
      bit [1:0] exp_step = expected_enc_q.pop_front();
      `uvm_info("ENC_CHECKER", $sformatf("Quadrature Step Match: enc_a=%0b, enc_b=%0b", item.enc_a, item.enc_b), UVM_LOW)
      enc_matches++;
    end
    if (item.enc_fault === 1'b1) begin
      `uvm_error("ENC_CHECKER", "Encoder reported unexpected fault")
      enc_mismatches++;
    end
  endfunction

  // 4. PWM Monitor Analysis Implementation (Passive Observation)
  virtual function void write_pwm(pwm_item item);
    pwm_samples++;
    `uvm_info("PWM_CHECKER", $sformatf("Passive PWM sample observed: PWM_OUT=%0b", item.PWM_OUT), UVM_HIGH)
  endfunction

  // Final Reporting
  virtual function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("SOC_CHECKER_SUMMARY", "==================================================", UVM_LOW)
    `uvm_info("SOC_CHECKER_SUMMARY", $sformatf("GPIO Checks   : Matches=%0d, Mismatches=%0d", gpio_matches, gpio_mismatches), UVM_LOW)
    `uvm_info("SOC_CHECKER_SUMMARY", $sformatf("UART Checks   : Valid Samples=%0d", uart_rx_checks), UVM_LOW)
    `uvm_info("SOC_CHECKER_SUMMARY", $sformatf("Encoder Checks: Step Matches=%0d, Faults=%0d", enc_matches, enc_mismatches), UVM_LOW)
    `uvm_info("SOC_CHECKER_SUMMARY", $sformatf("PWM Checks    : Passive Samples Observed=%0d", pwm_samples), UVM_LOW)
    `uvm_info("SOC_CHECKER_SUMMARY", "==================================================", UVM_LOW)

    if (gpio_matches == 0)    `uvm_error("SOC_CHECKER_SUMMARY", "Zero GPIO matches observed!")
    if (uart_rx_checks == 0)  `uvm_error("SOC_CHECKER_SUMMARY", "Zero UART RX checks observed!")
    if (enc_matches == 0)     `uvm_error("SOC_CHECKER_SUMMARY", "Zero Encoder step matches observed!")
    if (pwm_samples == 0)     `uvm_error("SOC_CHECKER_SUMMARY", "Zero PWM samples observed!")

    if (expected_gpio_q.size() > 0)
      `uvm_error("SOC_CHECKER_SUMMARY", $sformatf("%0d GPIO expected patterns were not observed!", expected_gpio_q.size()))
    if (expected_enc_q.size() > 0)
      `uvm_error("SOC_CHECKER_SUMMARY", $sformatf("%0d Encoder expected steps were not observed!", expected_enc_q.size()))
  endfunction
endclass
